insert into public.products (external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge) values ('prod-koraza-5', 'PNT-EXT-001', 'Koraza 5 Años Protección Total', 'Pintura elastomérica exterior antihongos con máxima resistencia a la intemperie y rayos UV', 'Pintura para exteriores 100% acrílica, base agua, diluible con agua. Máxima durabilidad con tecnología biosida activa contra hongos y algas. Puentea microfisuras de hasta 0.5 mm y repele agua de lluvia mientras permite transpirar al muro.', (select id from public.brands where name='Pintuco'), (select id from public.categories where kind='PRODUCT' and name='Fachadas & Exteriores'), 'Exterior', 'Mate', '20 a 25 m²/galón a 2 manos sobre superficie sellada', 22, 'Al tacto: 1 hora | Entre manos: 2 a 3 horas', array['Garantía de durabilidad de 5 años certificada', 'Puenteo elástico de microfisuras hasta 0.5 mm', 'Alta resistencia a la radiación UV y decoloración', 'Excelente lavabilidad y bajo ensuciamiento', 'Bajo olor y cero solventes agresivos (Bajo VOC)']::text[], 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/koraza-5-anos.pdf', 4.9, 142, true, 'Más Vendido en Fachadas') on conflict (external_ref) do nothing;
