insert into public.products (external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge) values ('prod-aquablock-techos', 'PNT-IMP-003', 'Aquablock Fibratado Techos & Terrazas 8 Años', 'Impermeabilizante elastomérico reforzado con fibras para losas, cubiertas y terrazas transitables', 'Impermeabilizante acrílico con fibras incorporadas que sustituyen la tela de refuerzo en áreas continuas. Altamente elástico, no se cuartea con el sol y resiste el tránsito peatonal liviano y estancamientos temporales de agua.', (select id from public.brands where name='Pintuco'), (select id from public.categories where kind='PRODUCT' and name='Impermeabilizantes'), 'Exterior', 'Satinado', '1.2 a 1.5 L/m² en 3 manos cruzadas (aprox. 12 m²/galón sistema completo)', 12, 'Entre manos: 3 a 4 horas | Curado total: 48 horas', array['Garantía de estanqueidad de 8 años', 'Fibras de polímero que evitan desgarros estructurales', 'Refleja hasta el 85% de radiación solar (aislamiento térmico)', 'Puentea fisuras de contracción en losas de concreto', 'Fácil aplicación en frío con rodillo o brocha']::text[], 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/aquablock-techos.pdf', 4.9, 88, true, 'Máxima Impermeabilidad') on conflict (external_ref) do nothing;
