insert into public.products (external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge) values ('prod-sellador-antialcalino', 'PNT-PREP-004', 'Sellador Antialcalino Pintuco Base Agua', 'Imprimante fijador que neutraliza la eflorescencia salina y uniformiza la absorción', 'Imprimación esencial para muros nuevos o intervenidos de concreto y revoque. Bloquea sales y humedad residual proveniente del sustrato, previniendo el ampollamiento y la decoloración de la pintura de acabado.', (select id from public.brands where name='Pintuco'), (select id from public.categories where kind='PRODUCT' and name='Fachadas & Exteriores'), 'Ambos', 'Mate', '25 a 35 m²/galón a 1 mano', 30, 'Al tacto: 45 min | Repinte: 2 horas', array['Bloquea el salitre y la alcalinidad del cemento fresco', 'Mejora la adherencia de pinturas de fachada hasta un 60%', 'Ahorra pintura de acabado al sellar la porosidad', 'Secado ultrarrápido al tacto en 45 minutos']::text[], 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/sellador-antialcalino.pdf', 4.8, 95, true, 'Paso 1 Obligatorio') on conflict (external_ref) do nothing;
