insert into public.products (external_ref, code, name, tagline, description, brand_id, category_id, environment, finish, coverage, spread_rate_m2_per_gal, drying_time, features, image_url, tech_sheet_url, rating, reviews_count, is_popular, badge) values ('prod-masilla-elastomerica', 'PNT-PREP-005', 'Masilla Elastomérica Grietas & Fisuras Fachada', 'Masilla acrílica flexible para sello de fisuras y juntas con movimiento en exteriores', 'Compuesto elastomérico diseñado para sellar y reparar grietas de hasta 5 mm de ancho en muros exteriores e interiores. Gran elongación y memoria elástica, no se encoge ni se agrieta con la intemperie.', (select id from public.brands where name='Pintuco'), (select id from public.categories where kind='PRODUCT' and name='Fachadas & Exteriores'), 'Ambos', 'Texturizado', 'Rinde aprox. 15 metros lineales por cartucho de 300ml o 15 m² en fisurado general', 15, 'Al tacto: 2 horas | Lijado/Pintado: 12 horas', array['Elongación superior al 300% para absorber dilataciones térmicas', 'Pintable con cualquier vinilo o pintura elastomérica Pintuco', 'Excelente adherencia sobre concreto, mortero y mampostería', 'Uso interior y exterior bajo intemperie severa']::text[], 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&q=80&w=600', 'https://pintuco.com.co/fichas-tecnicas/masilla-elastomerica.pdf', 4.9, 74, true, 'Solución Antifisuras') on conflict (external_ref) do nothing;
