insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-01', 'Sistema Fachada Koraza Protección Extrema', (select id from public.categories where kind='SOLUTION' and name='Fachadas'), false, 'Sistema elastomérico bicapa de máxima durabilidad y repelencia al agua, diseñado para fachadas expuestas a intemperie severa, radiación UV y contaminación urbana.', 'https://images.unsplash.com/photo-1541888946425-d0fbb18086f6?auto=format&fit=crop&q=80&w=600', 'Más Solicitado', 'Fachadas de edificios, casas, muros perimetrales exteriores', 'Concreto, Mortero, Ladrillo limpio, Revoque', array['Puenteo de microfisuras de hasta 0.5 mm sin cuartearse', 'Hidrorrepelente con tecnología efecto loto autolimpiable con la lluvia', 'Protección antifúngica y antialgas por 5 a 7 años garantizados', 'Alta retención de color frente a luz solar directa y rayos UV']::text[], 'Sellador Antialcalino + Masilla Elastomérica + 2 Manos de Koraza', '5 a 7 años garantizados', '20-25 m²/galón a 2 manos (según rugosidad)', array['Galón (3.785 L)', 'Cuñete (5 Gal / 18.9 L)']::text[], array['Paso 1: Lavado a presión para retirar polvo, sales y material suelto.', 'Paso 2: Calafateo de fisuras con Masilla Elastomérica Pintuco.', 'Paso 3: Imprimación general con 1 mano de Sellador Antialcalino.', 'Paso 4: Aplicación de 2 manos cruzadas de Pintura Koraza 5 Años.']::text[], '[{"name":"Blanco Nieve","hex":"#F8FAFC"},{"name":"Arena Real","hex":"#FDE68A"},{"name":"Terracota","hex":"#EA580C"},{"name":"Gris Cemento","hex":"#94A3B8"},{"name":"Azul Pintuco","hex":"#004F9F"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-02', 'Sistema Viniltex Avanzado Cero Olor Antibacterial', (select id from public.categories where kind='SOLUTION' and name='Interiores'), false, 'Recubrimiento premium base agua de alta lavabilidad para ambientes interiores residenciales, comerciales e institucionales con requerimientos higiénicos.', 'https://images.unsplash.com/photo-1586023492125-27b2c045efd7?auto=format&fit=crop&q=80&w=600', 'Eco & Salud', 'Salas, habitaciones, oficinas, consultorios médicos, colegios', 'Drywall, Yeso, Estuco, Mampostería interior', array['Elimina el 99.9% de bacterias, hongos y virus en superficie', 'Ultra lavable con resistencia a más de 10,000 ciclos de frote', 'Bajo VOC y olor casi imperceptible para ocupación inmediata', 'Acabado mate sedoso uniforme de alta elegancia visual']::text[], 'Sellador Acrílico Interior + Estuco Profesional + 2 Manos Viniltex', 'Alta durabilidad lavable', '40-45 m²/galón a 2 manos', array['1/4 Galón', 'Galón', 'Cuñete (5 Gal)']::text[], array['Paso 1: Lijado suave y retiro de polvo residual.', 'Paso 2: Resane de imperfecciones con Estuco Acrílico.', 'Paso 3: Aplicación de 2 manos de Viniltex Avanzado con rodillo antigota.']::text[], '[{"name":"Blanco Puro","hex":"#FFFFFF"},{"name":"Marfil Suave","hex":"#FEF3C7"},{"name":"Gris Niebla","hex":"#E2E8F0"},{"name":"Celeste Zen","hex":"#E0F2FE"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-03', 'Sistema Pintuflex Impermeabilización Continua', (select id from public.categories where kind='SOLUTION' and name='Impermeabilización'), false, 'Membrana líquida elastomérica armada para cubiertas, terrazas, losas y techos con filtraciones o riesgo de estancamiento.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=600', 'Protección Total', 'Cubiertas planas, techos inclinados, terrazas transitables ligeras', 'Concreto, Mortero cementicio, Manto asfáltico envejecido', array['Elongación superior al 300% para absorber dilataciones térmicas severas', 'Refuerzo con velo de fibra de poliéster para cero empalmes ni juntas', 'Resistencia directa a rayos solares UV y choque térmico', 'Fácil mantenimiento preventivo sin levantar sustrato']::text[], 'Imprimación Acrílica Diluida + Velo de Poliéster + 3 Manos Pintuflex', '5, 7 o 10 años según espesor', '1 m²/litro a 3 manos con tela (aprox. 18 m²/cuñete)', array['Galón', 'Cuñete (5 Gal)']::text[], array['Paso 1: Limpieza profunda y regularización de pendientes hacia sifones.', 'Paso 2: Imprimación diluida con agua 1:3 para anclaje.', 'Paso 3: Colocación de tela de refuerzo embebida en primera mano pura.', 'Paso 4: Aplicación de segunda y tercera mano cruzadas.']::text[], '[{"name":"Blanco Térmico (Reflectivo)","hex":"#F8FAFC"},{"name":"Rojo Teja","hex":"#B91C1C"},{"name":"Gris Cemento","hex":"#64748B"},{"name":"Verde Cubierta","hex":"#15803D"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-04', 'Sistema Pintulux Anticorrosivo & Esmalte Metálico', (select id from public.categories where kind='SOLUTION' and name='Metal'), false, 'Sistema integral de protección catódica y esmalte sintético poliuretánico para estructuras metálicas, barandas, rejas y tanques expuestos.', 'https://images.unsplash.com/photo-1504917599217-d4dc5ebe6122?auto=format&fit=crop&q=80&w=600', null, 'Estructuras de acero, carpintería metálica, tuberías, techumbres', 'Acero al carbono, Hierro forjado, Metal galvanizado', array['Inhibidor activo contra la corrosión galvánica y salina', 'Excelente brillo, retención de color y dureza al impacto', 'Compatible con galvanizado previo acondicionador de superficie']::text[], 'Desengrasante + Anticorrosivo Cromato/Fosfato + Esmalte Pintulux', '3 a 5 años en ambientes urbanos', '25-30 m²/galón a 2 manos', array['1/4 Galón', 'Galón', 'Tambor (55 Gal)']::text[], array['Paso 1: Desoxidado manual o mecánico (lija grano 80 / cepillo de alambre).', 'Paso 2: Desengrase con solvente Pintuco.', 'Paso 3: 1 mano de Anticorrosivo Pintuco antes de 4 horas.', 'Paso 4: 2 manos de Esmalte Sintético Pintulux.']::text[], '[{"name":"Negro Brillante","hex":"#0F172A"},{"name":"Azul Pintuco","hex":"#004F9F"},{"name":"Gris Máquina","hex":"#475569"},{"name":"Verde Foresta","hex":"#166534"},{"name":"Aluminio Metal","hex":"#94A3B8"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-05', 'Sistema Maderin Preservante & Barniz Marino', (select id from public.categories where kind='SOLUTION' and name='Madera'), false, 'Tratamiento fungicida, insecticida e hidrófugo con acabado transparente o tonalizado para decks, pérgolas y carpintería de madera noble.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?auto=format&fit=crop&q=80&w=600', null, 'Pérgolas exteriores, puertas macizas, decks de piscina, muebles de madera', 'Maderas duras, Pino tratado, Teca, Cedro', array['Filtro solar UV que previene el agrisamiento de la veta', 'Protege contra termitas, carcoma y pudrición por humedad', 'Microporoso: permite que la madera respire sin descascararse']::text[], 'Lijado grano fino + Inmunizante Maderin + 3 Manos Barniz Marino', '2 a 4 años según exposición', '30-35 m²/galón a 1 mano', array['1/4 Galón', 'Galón']::text[], array['Paso 1: Lijado en sentido de la veta y retiro total de aserrín.', 'Paso 2: Impregnación fungicida con Inmunizante Maderin.', 'Paso 3: 3 manos de Barniz Marino con lijado intermedio ultra fino.']::text[], '[{"name":"Transparente Natural","hex":"#FEF3C7"},{"name":"Teca Cálida","hex":"#B45309"},{"name":"Caoba Intenso","hex":"#78350F"},{"name":"Nogal Clásico","hex":"#451A03"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-06', 'Sistema Pintuepox Tráfico Pesado & Pisos Industriales', (select id from public.categories where kind='SOLUTION' and name='Industrial'), false, 'Recubrimiento bicomponente epóxico y poliuretano alifático para plantas industriales, talleres, hangares y zonas de alto impacto químico/mecánico.', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&q=80&w=600', 'Industrial Pesado', 'Pisos de fábricas, almacenes, zonas de carga, cocinas industriales', 'Concreto pulido, losas industriales, pisos con acabado CSP 3-4', array['Resistencia a derrames de aceites, solventes y ácidos diluidos', 'Soporta tráfico constante de montacargas de hasta 10 toneladas', 'Acabado antideslizante opcional con agregado de sílice calibrada', 'Fácil descontaminación y cumplimiento de normas sanitarias BPM']::text[], 'Perfilado Mecánico + Primer Epóxico 100% + Capa de Alto Espesor', '5 a 10 años con mantenimiento', '14-18 m²/galón según espesor en mils', array['Kit Galón (A+B)', 'Kit Cuñete (A+B)']::text[], array['Paso 1: Granallado o escarificado para perfil CSP-3.', 'Paso 2: Desengrase profundo y verificación de humedad < 4%.', 'Paso 3: Imprimación epóxica 100% sólidos.', 'Paso 4: Aplicación de capa auto-nivelante Pintuepox.']::text[], '[{"name":"Gris Tráfico","hex":"#64748B"},{"name":"Verde Seguridad","hex":"#15803D"},{"name":"Amarillo Señalización","hex":"#EAB308"},{"name":"Azul Industrial","hex":"#1E40AF"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, badge, application, surface_summary, features, system_summary, durability_estimate, spread_rate_info, packagings, step_by_step_guide, color_swatches) values ('sol-07', 'Sistema Solución Express Mantenimiento Institucional', (select id from public.categories where kind='SOLUTION' and name='Mantenimiento'), false, 'Kit de intervención rápida para reparaciones puntuales de humedad por capilaridad, salitre, desconche y retoques inmediatos en inmuebles operativos.', 'https://images.unsplash.com/photo-1503387762-592deb58ef4e?auto=format&fit=crop&q=80&w=600', null, 'Mantenimiento locativo en centros comerciales, colegios, bancos', 'Muros mixtos, zócalos, cielo rasos', array['Secado ultra rápido al tacto en menos de 30 minutos', 'Bloqueador de manchas de humo, grasa y humedad previa', 'Fácil aplicación sin necesidad de evacuar áreas adyacentes']::text[], 'Limpieza de eflorescencia + Bloqueador de Manchas + Acabado', 'Solución preventiva inmediata', '30 m²/galón', array['1/4 Galón', 'Galón']::text[], array['Paso 1: Cepillado de eflorescencias de salitre.', 'Paso 2: Bloqueador antihumedad Pintuco.', 'Paso 3: Acabado rápido.']::text[], '[{"name":"Blanco Universal","hex":"#FFFFFF"},{"name":"Gris Suave","hex":"#F1F5F9"}]'::jsonb) on conflict (external_ref) do nothing;
insert into public.solutions (external_ref, name, category_id, is_kit, description, image_url, subtitle, problem_target, ideal_for, warranty, discount_percent, tools_included) values ('kit-fachada-5anos', 'Kit Fachada 5 Años Antifisuras & Humedad', (select id from public.categories where kind='SOLUTION' and name='Fachadas & Exteriores'), true, 'Fachada con microfisuras, humedad de lluvia y desgaste por intemperie', 'https://images.unsplash.com/photo-1590381105924-c72589b9ef3f?auto=format&fit=crop&q=80&w=800', 'El sistema completo especificado para fachadas residenciales y comerciales de 85 m²', 'Fachada con microfisuras, humedad de lluvia y desgaste por intemperie', 'Edificios residenciales, casas campestres y fachadas de locales en concreto', 'Garantía Pintuco 5 Años en Sistema Completo', 12, array['1 Rodillo Microfibra Antigota 9"', '1 Brocha Master Cerdas Mixtas 3"', '2 Rollos de Cinta Azul Masking Tape 1.5"', 'Guía técnica paso a paso de aplicación Pintuco']::text[]) on conflict (external_ref) do nothing;
