insert into public.solution_products (solution_id, product_id, variant_id, presentation_label, unit_price_cop, step_number, phase, role_description, quantity_for_85m2, image_url, sort_order) values ((select id from public.solutions where external_ref='kit-metal-antioxidante'), (select id from public.products where external_ref='prod-pintulux-3en1'), (select v.id from public.product_variants v join public.products pr on pr.id=v.product_id where pr.external_ref='prod-pintulux-3en1' and v.label='1 Galón (3.785 L)'), '1 Galón (3.785 L)', 124900, 2, 'Acabado', 'Neutraliza el óxido y proporciona acabado brillante de alta protección.', 2, 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&q=80&w=400', 2) on conflict (solution_id, step_number) do nothing;
